       @PEutt.peutt E MN MF FI FC MX FO A B RS (@PTreeDefinition.PTree.bind E MN R1 A t1 k1)
         (@PTreeDefinition.PTree.bind E MN R2 B t2 k2)

@BindScheduling.ptree_bind_global_le_diagonal
     : forall (E MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       (forall (A B : Type) (x : A) (k : A -> MF B),
        @Omega.sem_le MF FI FO B (@Measure.sem_bind MF FI A B (@Measure.sem_ret MF FI A x) k) (k x) /\
        @Omega.sem_le MF FI FO B (k x) (@Measure.sem_bind MF FI A B (@Measure.sem_ret MF FI A x) k)) ->
       (forall (A B C : Type) (mu : MN A) (k : A -> MF B) (h : B -> MF C),
        @Omega.sem_le MF FI FO C
          (@Measure.sem_bind MF FI B C (@Mixed.mixed_bind MN MF MX A B mu k) h)
          (@Mixed.mixed_bind MN MF MX A C mu (fun x : A => @Measure.sem_bind MF FI B C (k x) h)) /\
        @Omega.sem_le MF FI FO C
          (@Mixed.mixed_bind MN MF MX A C mu (fun x : A => @Measure.sem_bind MF FI B C (k x) h))
          (@Measure.sem_bind MF FI B C (@Mixed.mixed_bind MN MF MX A B mu k) h)) ->
       (forall (A B : Type) (mu : MN A) (k h : A -> MF B),
        (forall x : A, @Omega.sem_le MF FI FO B (k x) (h x)) ->
        @Omega.sem_le MF FI FO B (@Mixed.mixed_bind MN MF MX A B mu k)
          (@Mixed.mixed_bind MN MF MX A B mu h)) ->
       forall (A B : Type) (n : nat) (t : PTreeDefinition.ptree E MN A)
         (k : A -> PTreeDefinition.ptree E MN B),
       @Omega.sem_le MF FI FO (UnifiedFrontier.stable_head E MN B)
         (@PTreeKernel.ptree_hitting_approx E MN MF FI MX FO B n
            (@PTreeDefinition.observe E MN B (@PTreeDefinition.PTree.bind E MN A B t k)))
         (@BindScheduling.ptree_bind_split_approx E MN MF FI MX FO A B n n t k)

@BindScheduling.ptree_bind_split_le_global
     : forall (E MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       (forall (A B : Type) (x : A) (k : A -> MF B),
        @Omega.sem_le MF FI FO B (@Measure.sem_bind MF FI A B (@Measure.sem_ret MF FI A x) k) (k x) /\
        @Omega.sem_le MF FI FO B (k x) (@Measure.sem_bind MF FI A B (@Measure.sem_ret MF FI A x) k)) ->
       (forall (A B : Type) (k : A -> MF B),
        @Omega.sem_le MF FI FO B (@Measure.sem_bind MF FI A B (@Omega.sem_zero MF FI FO A) k)
          (@Omega.sem_zero MF FI FO B)) ->
       (forall (A B C : Type) (mu : MN A) (k : A -> MF B) (h : B -> MF C),
        @Omega.sem_le MF FI FO C
          (@Measure.sem_bind MF FI B C (@Mixed.mixed_bind MN MF MX A B mu k) h)
          (@Mixed.mixed_bind MN MF MX A C mu (fun x : A => @Measure.sem_bind MF FI B C (k x) h)) /\
        @Omega.sem_le MF FI FO C
          (@Mixed.mixed_bind MN MF MX A C mu (fun x : A => @Measure.sem_bind MF FI B C (k x) h))
          (@Measure.sem_bind MF FI B C (@Mixed.mixed_bind MN MF MX A B mu k) h)) ->
       (forall (A B : Type) (mu : MN A) (k h : A -> MF B),
        (forall x : A, @Omega.sem_le MF FI FO B (k x) (h x)) ->
        @Omega.sem_le MF FI FO B (@Mixed.mixed_bind MN MF MX A B mu k)
          (@Mixed.mixed_bind MN MF MX A B mu h)) ->
       forall (A B : Type) (n m : nat) (t : PTreeDefinition.ptree E MN A)
         (k : A -> PTreeDefinition.ptree E MN B),
       @Omega.sem_le MF FI FO (UnifiedFrontier.stable_head E MN B)
         (@BindScheduling.ptree_bind_split_approx E MN MF FI MX FO A B n m t k)
         (@PTreeKernel.ptree_hitting_approx E MN MF FI MX FO B (n + m)
            (@PTreeDefinition.observe E MN B (@PTreeDefinition.PTree.bind E MN A B t k)))

@BindScheduling.ptree_bind_cofinal_all
     : forall (E MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       (forall (A B : Type) (x : A) (k : A -> MF B),
        @Omega.sem_le MF FI FO B (@Measure.sem_bind MF FI A B (@Measure.sem_ret MF FI A x) k) (k x) /\
        @Omega.sem_le MF FI FO B (k x) (@Measure.sem_bind MF FI A B (@Measure.sem_ret MF FI A x) k)) ->
       (forall (A B : Type) (k : A -> MF B),
        @Omega.sem_le MF FI FO B (@Measure.sem_bind MF FI A B (@Omega.sem_zero MF FI FO A) k)
          (@Omega.sem_zero MF FI FO B)) ->
       (forall (A B C : Type) (mu : MN A) (k : A -> MF B) (h : B -> MF C),
        @Omega.sem_le MF FI FO C
          (@Measure.sem_bind MF FI B C (@Mixed.mixed_bind MN MF MX A B mu k) h)
          (@Mixed.mixed_bind MN MF MX A C mu (fun x : A => @Measure.sem_bind MF FI B C (k x) h)) /\
        @Omega.sem_le MF FI FO C
          (@Mixed.mixed_bind MN MF MX A C mu (fun x : A => @Measure.sem_bind MF FI B C (k x) h))
          (@Measure.sem_bind MF FI B C (@Mixed.mixed_bind MN MF MX A B mu k) h)) ->
       (forall (A B : Type) (mu : MN A) (k h : A -> MF B),
        (forall x : A, @Omega.sem_le MF FI FO B (k x) (h x)) ->
        @Omega.sem_le MF FI FO B (@Mixed.mixed_bind MN MF MX A B mu k)
          (@Mixed.mixed_bind MN MF MX A B mu h)) ->
       (forall (A : Type) (c d : nat -> MF A) (out : MF A),
        @Omega.sem_increasing MF FI FO A c ->
        @Omega.sem_increasing MF FI FO A d ->
        (forall n : nat, exists m : nat, @Omega.sem_le MF FI FO A (c n) (d m)) ->
        (forall n : nat, exists m : nat, @Omega.sem_le MF FI FO A (d n) (c m)) ->
        @Omega.sem_lub MF FI FO A c out <-> @Omega.sem_lub MF FI FO A d out) ->
       forall (A B : Type) (t : PTreeDefinition.ptree E MN A)
         (k : A -> PTreeDefinition.ptree E MN B),
       @PTreeKernel.ptree_bind_cofinal E MN MF FI MX FO A B t k

